RECORDS = []
def add(n, name, date, issuer, title, sections, ext='pdf', recipient='bauherr', **extra):
    def normal(value):
        if isinstance(value,str):
            value=re.sub(r'(?<=[a-zäöüß])(?=\d)', ' ', value)
            value = re.sub(r'(?<=\d)(?=[a-zA-ZäöüÄÖÜß])', ' ', value)
            value = re.sub(r'((?:§|Absatz)\s*\d+)\s+([a-z])\b', r'\1\2', value)
            return re.sub(r'§\s*(\d+)', r'§ \1', value)
        return type(value)(normal(x) for x in value) if isinstance(value,(list,tuple)) else value
    sections=normal(sections)
    d=dict(number=n,filename=f'{n:03d}_{name}.{ext}',date=date,issuer=issuer,recipient=recipient,title=normal(title),sections=sections,**extra);RECORDS.append(d);return d

