          ('t',[['Bereich','Feststellung'],['Räume und Oberflächen','Räume besenrein, Fenster und Türen gemeinsam betätigt. '+('Der vorhandene Eichenbelag wurde gezeigt; die Vermieterin klärt dessen abweichende Qualität mit dem Ausbauunternehmen.' if idx==7 else 'Im sichtbaren Bereich keine zusätzlich protokollierten Beschädigungen.')],['Sanitär und Heizung','Armaturen und WC geprüft, Thermostate erklärt, keine sichtbare Leckage'],['Schlüssel','3 Wohnungs-/Haustürschlüssel und2 Briefkastenschlüssel'],['Stromzähler',f'SW-E-{idx:02d}; Stand {12+idx*3},0kWh'],['Kaltwasser',f'SW-K-{idx:02d}; Stand {1.2+idx*.1:.1f}m³'],['Warmwasser',f'SW-W-{idx:02d}; Stand {0.6+idx*.1:.1f}m³'],['Wärmezähler',f'SW-H-{idx:02d}; Stand {0.040+idx*.003:.3f}MWh'],['Stellplatz',f'Pkw-Platz{idx:02d} gezeigt; Zugang und Zuordnung erläutert']],[130,365]),
